import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as p,o as t,af as s,b as n,w as a,a as r,G as l,ag as h}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const _=JSON.parse('{"title":"Codex App 与 CLI 的第三方模型和双配置","description":"分清配置目录、认证、模型目录与代理路由，复用官方和 API 两套配置，并验证恢复官方默认模型。","frontmatter":{"title":"Codex App 与 CLI 的第三方模型和双配置","description":"分清配置目录、认证、模型目录与代理路由，复用官方和 API 两套配置，并验证恢复官方默认模型。","domain":"product","tags":["coding-agent","configuration"],"role":"tutorial","topicId":"codex-model-providers"},"headers":[],"relativePath":"zh/products/codex/model-providers.md","filePath":"zh/products/codex/model-providers.md","lastUpdated":1791173509000}'),c={name:"zh/products/codex/model-providers.md"};function k(E,e,g,u,C,m){const i=o("Mermaid");return t(),p("div",null,[e[1]||(e[1]=s(`<h1 id="codex-app-与-cli-的第三方模型和双配置" tabindex="-1">Codex App 与 CLI 的第三方模型和双配置 <a class="header-anchor" href="#codex-app-与-cli-的第三方模型和双配置" aria-label="Permalink to &quot;Codex App 与 CLI 的第三方模型和双配置&quot;">​</a></h1><p><strong>先把官方登录保留在 <code>~/.codex</code>，再用 <code>~/.codex-api</code> 试第三方模型。App 与 CLI 在同一种模式下读取同一个目录；切换模式时改变启动环境，不来回复制 <code>auth.json</code>。</strong> 第三方接入能否完成，取决于协议、认证、模型目录和客户端版本四个条件。[S1][S2][E1]</p><p>本文把一次 Windows 原生 Codex 配置检查改写成通用教程。核验日期为 <strong>2026-09-03</strong>：CLI <code>0.153.0</code>、App 内置运行时 <code>0.153.0-alpha.5</code>、桌面包 <code>26.901.1978.0</code>、OpenCodex <code>2.14.0</code>。这些是实验版本，不是最低支持版本。[E1]</p><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><h3 id="先解决哪个问题" tabindex="-1">先解决哪个问题 <a class="header-anchor" href="#先解决哪个问题" aria-label="Permalink to &quot;先解决哪个问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的目标</th><th>推荐做法</th><th>需要额外核验</th></tr></thead><tbody><tr><td>App 和 CLI 共用官方 ChatGPT 登录</td><td>两者使用默认 <code>~/.codex</code> 与同一认证存储后端</td><td>新进程读取的 HOME、登录类型、官方模型列表</td></tr><tr><td>CLI 临时试一个兼容模型</td><td>命名 profile，或独立 API HOME</td><td>CLI 的 <code>--profile</code> 行为与协议支持</td></tr><tr><td>App 和 CLI 都切换到第三方</td><td>启动前共同选择 API HOME，在其根配置指定 provider</td><td>App 是否实际接收该 HOME、模型选择器、一次真实请求</td></tr><tr><td>同一个列表显示多个上游模型</td><td>能识别路由模型 ID 的代理，例如 OpenCodex</td><td>路由规则、代理认证、服务启动与退出恢复</td></tr><tr><td>恢复纯官方模式</td><td>移除第三方覆盖，停止代理与自启动，再重启客户端</td><td>不能只看配置文件或服务停止提示</td></tr></tbody></table><p><strong>先决条件</strong>：能编辑 TOML，了解环境变量，会在 PowerShell 或终端检查进程；第三方服务需要你自行取得授权。<strong>学习目标</strong>：解释每个文件的职责、建立两套可选择配置、识别模型显示与请求成功的区别、恢复官方默认。[S1][S2]</p><p>范围是本机 App 与 CLI 的配置。本文不承诺任意“OpenAI 兼容”接口都可使用，不扩展到云端 Codex，也不提供个人账号、真实服务地址或认证文件。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><h3 id="第一步-给两种模式各留一个-home" tabindex="-1">第一步：给两种模式各留一个 HOME <a class="header-anchor" href="#第一步-给两种模式各留一个-home" aria-label="Permalink to &quot;第一步：给两种模式各留一个 HOME&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.codex/                      官方模式：App + CLI</span></span>
<span class="line"><span>  config.toml                  用户配置</span></span>
<span class="line"><span>  auth.json                    文件存储模式下的官方登录，私密</span></span>
<span class="line"><span>~/.codex-api/                  API 模式：App + CLI</span></span>
<span class="line"><span>  config.toml                  第三方 provider 配置</span></span>
<span class="line"><span>  catalog.json                 可选：与运行时兼容的模型目录</span></span></code></pre></div><p><code>CODEX_HOME</code> 不只影响配置，还影响认证和本地状态。两套 HOME 会形成两份会话与缓存；<strong>同一模式共用一个 HOME</strong> 才是本文的“复用”。独立 HOME 不意味着自动共享 MCP、插件、技能和历史；确实需要复用的非敏感设置应有自己的来源与同步方式。[S1][E1]</p><p>下载模板：<a href="/examples/codex-config/official.config.toml.html">官方配置</a>、<a href="/examples/codex-config/third-party.config.toml.html">第三方配置</a>、<a href="/examples/codex-config/catalog.example.json">模型目录示例</a>、<a href="/examples/codex-config/Start-Codex.ps1.html">Windows 启动脚本</a>。将模板<strong>合并到目标文件</strong>，不要覆盖已有的 MCP、项目规则或插件配置。</p><p>官方模式不需要手写模型名称、模型目录或服务地址。为了明确使用本机文件认证，模板只包含：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cli_auth_credentials_store = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file&quot;</span></span></code></pre></div><p>使用 <code>keyring</code> 或 <code>auto</code> 时，凭据位置会不同；先确认现有后端再决定是否更改。不要为了“共享”把 API key 写进官方 <code>auth.json</code>。同一 HOME、同一存储后端下的登录与退出可能影响两个入口。[S2]</p><h3 id="第二步-配置一个-responses-兼容的上游" tabindex="-1">第二步：配置一个 Responses 兼容的上游 <a class="header-anchor" href="#第二步-配置一个-responses-兼容的上游" aria-label="Permalink to &quot;第二步：配置一个 Responses 兼容的上游&quot;">​</a></h3><p>把下面配置放进 <strong>API HOME 的 <code>config.toml</code></strong>。<code>example_gateway</code>、模型 ID、域名均为占位符，需要按上游文档替换：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example_gateway&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;provider-model-id&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">example_gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Example Responses gateway&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://gateway.example.com/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EXAMPLE_MODEL_API_KEY&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wire_api = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;responses&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">supports_websockets = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>在核验版本中，<code>wire_api</code> 仅接受 <code>responses</code>。只支持 <code>/chat/completions</code> 的接口需要协议适配层。<code>supports_websockets = false</code> 只是禁用可选传输；它不会修复错误的 Responses 事件流、工具调用或模型 ID。[S3]</p><p>从本地凭据管理器给启动进程提供 <code>EXAMPLE_MODEL_API_KEY</code>，不要把真实值写入模板、命令历史或 PR。App 从桌面图标启动时未必继承终端变量；需要令真正启动 App 的进程取得变量。也可使用官方支持的 <code>[model_providers.&lt;id&gt;.auth]</code> 命令型认证，从凭据管理器取短期 token；不得同时配置 <code>env_key</code>、内联 bearer 或 <code>requires_openai_auth</code>。[S1][S3]</p><p><code>requires_openai_auth = true</code> 会选择 OpenAI 认证，并忽略 <code>env_key</code>；只有明确需要 OpenAI 登录透传的可信代理才使用它，不能把它当作“开启第三方支持”的开关。[S2]</p><h3 id="第三步-让-app-与-cli-选择同一模式" tabindex="-1">第三步：让 App 与 CLI 选择同一模式 <a class="header-anchor" href="#第三步-让-app-与-cli-选择同一模式" aria-label="Permalink to &quot;第三步：让 App 与 CLI 选择同一模式&quot;">​</a></h3><p><strong>Windows 原生</strong>：在已配置好密钥环境的 PowerShell 中运行下载的启动脚本：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-Codex.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mode official </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Surface cli</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-Codex.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mode api </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Surface cli</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-Codex.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mode official </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Surface app</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-Codex.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mode api </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Surface app</span></span></code></pre></div><p>这四条是<strong>备选操作</strong>，按需要运行一条。脚本仅在启动期间设置进程级 <code>CODEX_HOME</code>，随后恢复调用终端的值。启动 App 前要求完全退出旧实例，并从已安装 MSIX 包发现可执行文件。安装布局变化会明确报错。[E2]</p><p><strong>验收 HOME</strong>：在 App 的设置中打开实际配置文件，核对路径；再核对其内置 app-server 的 <code>config/read</code>。不能用另一个终端里的 <code>$env:CODEX_HOME</code> 证明 GUI 已切换。若安装方式忽略启动环境，先停止切换并查清真实配置入口；不要盲目删除默认目录或创建目录联接。该脚本的语法已验证，跨所有安装方式的 GUI 切换尚未验证。[S4][E2]</p><p><strong>macOS / Linux CLI</strong>：变量只作用于本次进程：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.codex&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> codex</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.codex-api&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> codex</span></span></code></pre></div><p>macOS GUI 可由终端向实际 App 可执行文件传递同一环境，但需要先确认安装路径并完全退出旧实例。本次没有验证 macOS GUI 双 HOME 启动，不将其写成通用复制命令。[E1]</p><h3 id="第四步-需要模型选择器时再增加目录" tabindex="-1">第四步：需要模型选择器时再增加目录 <a class="header-anchor" href="#第四步-需要模型选择器时再增加目录" aria-label="Permalink to &quot;第四步：需要模型选择器时再增加目录&quot;">​</a></h3><p><code>model</code> 选择请求使用的模型；<code>model_catalog_json</code> 提供启动时加载的模型元数据。两者职责不同。模型目录示例是完整的、用于结构测试的虚构条目；上下文长度、推理档位、图片和工具能力必须按真实上游填写。[S3][E2]</p><p>在 API 配置的<strong>第一个表头之前</strong>加入实际绝对路径，例如：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_catalog_json = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;C:\\Users\\Example\\.codex-api\\catalog.json&#39;</span></span></code></pre></div><p>将 <code>Example</code> 替换为本机用户目录。TOML 中表头后的键属于该表：把这行放在 <code>[model_providers.example_gateway]</code> 后面会写到错误层级。</p><p>先按各自的真实可执行文件验证目录：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex debug models </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">help</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;model_catalog_json=&quot;C:\\Users\\Example\\.codex-api\\catalog.json&quot;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> debug models</span></span></code></pre></div><p>随后用 <strong>App 内置的 <code>codex.exe</code></strong> 重复同一检查，再重启 App 看选择器。全局 CLI 与 App 可能打包不同版本。不要直接把上游 <code>main</code> 分支的目录当作跨版本通用文件；已有版本不兼容的可复现报告。[S5][E2]</p><h3 id="第五步-需要时才引入-opencodex" tabindex="-1">第五步：需要时才引入 OpenCodex <a class="header-anchor" href="#第五步-需要时才引入-opencodex" aria-label="Permalink to &quot;第五步：需要时才引入 OpenCodex&quot;">​</a></h3><p>OpenCodex 是本地代理：它把带路由前缀的模型 ID 分发到相应 provider，也会修改 Codex 的模型目录和连接配置。在 <code>2.14.0</code> 的文档中，loopback 集成写入顶层 <code>openai_base_url</code>；非 loopback 使用命名 provider。它另有自己的 <code>OPENCODEX_HOME</code>，不能与 <code>CODEX_HOME</code> 混为一谈。[S6][E1]</p>`,40)),(t(),n(h,null,{default:a(()=>[l(i,{id:"mermaid-175",class:"mermaid",graph:"flowchart%20LR%0A%20%20App%5BCodex%20App%5D%20--%3E%20Home%5B%E6%89%80%E9%80%89%20CODEX_HOME%5D%0A%20%20CLI%5BCodex%20CLI%5D%20--%3E%20Home%0A%20%20Home%20--%3E%20Runtime%5BCodex%20%E8%BF%90%E8%A1%8C%E6%97%B6%5D%0A%20%20Runtime%20--%3E%7C%E7%9B%B4%E6%8E%A5%20provider%7C%20API%5BResponses%20%E5%85%BC%E5%AE%B9%E6%9C%8D%E5%8A%A1%5D%0A%20%20Runtime%20--%3E%7C%E4%BB%A3%E7%90%86%E8%B7%AF%E7%94%B1%7C%20Proxy%5B%E6%9C%AC%E5%9C%B0%20OpenCodex%5D%0A%20%20Proxy%20--%3E%20Upstream%5B%E4%B8%80%E4%B8%AA%E6%88%96%E5%A4%9A%E4%B8%AA%E4%B8%8A%E6%B8%B8%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<p>在隔离测试目录下安装并阅读当前帮助，再初始化；<code>ocx init</code> 会修改所选 Codex 配置：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_HOME </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;.codex-api&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENCODEX_HOME </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;.opencodex-lab&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g @bitkyc08</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opencodex@2.14.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ocx </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">help</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ocx init</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ocx start</span></span></code></pre></div><p>完成后退出这个测试终端，避免环境变量影响下一次官方启动。provider 的认证与模型选择按 <a href="https://opencodex.me/guides/providers/" target="_blank" rel="noreferrer">OpenCodex Providers</a> 配置；这里不复制生产配置。官方 ChatGPT 登录透传、API key 路由、账号池是三种不同关系，不能通过修改模型名称相互替代。[S6][S7]</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="五个状态不能互相证明" tabindex="-1">五个状态不能互相证明 <a class="header-anchor" href="#五个状态不能互相证明" aria-label="Permalink to &quot;五个状态不能互相证明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>谁负责</th><th>不能证明什么</th></tr></thead><tbody><tr><td>配置目录</td><td>启动进程与 <code>CODEX_HOME</code></td><td>不能证明已有 GUI 进程重新加载</td></tr><tr><td>认证</td><td>provider 的认证方式与凭据存储</td><td>key 存在不代表有效或有模型权限</td></tr><tr><td>路由</td><td><code>model_provider</code>、provider URL，或代理覆盖</td><td>模型名称像 GPT 不代表直连官方</td></tr><tr><td>模型目录</td><td><code>model_catalog_json</code>、缓存、运行时内置/远端数据</td><td>列表可见不代表能完成推理</td></tr><tr><td>当前任务</td><td>创建或恢复任务时采用的配置</td><td>全局默认更改不代表历史任务自动迁移</td></tr></tbody></table><p>以上分层来自配置接口与此次实证；排障应分别取证。[S1][S3][S4][E1]</p><h3 id="home-与-profile-怎么取舍" tabindex="-1">HOME 与 profile 怎么取舍 <a class="header-anchor" href="#home-与-profile-怎么取舍" aria-label="Permalink to &quot;HOME 与 profile 怎么取舍&quot;">​</a></h3><p><strong>HOME 用来隔离本地状态；profile 是同一 HOME 中的配置覆盖层。</strong> 在 <code>0.134.0</code> 及以后，CLI <code>--profile gateway</code> 读取 <code>$CODEX_HOME/gateway.config.toml</code>，旧 <code>[profiles.gateway]</code> 与顶层 <code>profile = &quot;gateway&quot;</code> 不再适用。[S1]</p><p>只在 CLI 临时切换时，可将第三方模板保存成 <code>gateway.config.toml</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span></span></code></pre></div><p>App 是否提供相同 profile 选择入口，要按安装版本核验。本文的双入口方案把选定 provider 放在各 HOME 的根 <code>config.toml</code>，不依赖 GUI 认识 CLI flag。[E1]</p><p><code>models_cache.json</code> 是派生数据，不是配置真源。此次 Windows 检查中，两个 HOME 同时存在代理目录与数百条缓存项；停止服务后仍需要移除覆盖并重启。官方模型管理器也分别处理缓存刷新和静态目录。[E1][S8]</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><h3 id="实战-把实验机恢复为官方默认" tabindex="-1">实战：把实验机恢复为官方默认 <a class="header-anchor" href="#实战-把实验机恢复为官方默认" aria-label="Permalink to &quot;实战：把实验机恢复为官方默认&quot;">​</a></h3><p>此次处理前，官方 HOME 保留 ChatGPT 认证但被代理改了默认模型与目录；API HOME 使用独立 API 认证。旧 GUI 切换脚本依赖目录联接，而现场已是普通目录；API 配置还给子进程注入了失效的 HOME 路径。这些是该机器的观察，不能推广为 Codex 的默认行为。[E1]</p><p>恢复顺序如下，先核对清单再操作：</p><ol><li><strong>在原机保存必要恢复材料</strong>，限制访问或加密；不上传 <code>auth.json</code>、环境文件、日志、历史数据库或代理账号数据。</li><li>完全退出 App 与需要重新加载配置的 CLI。保留正常的官方登录文件。</li><li>在卸载 CLI 包之前停止 OpenCodex 并移除其自启动；按当前帮助执行 <code>ocx service stop</code>、<code>ocx service uninstall</code>。<code>ocx restore</code> 只恢复配置，并不停止代理。[S9]</li><li>从生效配置移除第三方 <code>model</code>、<code>model_provider</code>、<code>model_catalog_json</code>、base URL 覆盖与 <code>[model_providers.*]</code>；清理相应 <code>*.config.toml</code>、认证辅助脚本、代理注入文件、过期模型缓存。保留无关 MCP 与项目配置。</li><li>清理启动脚本、用户环境和 <code>shell_environment_policy.set</code> 中的旧 HOME、模型 key 与代理覆盖。不要误删其他应用仍使用的凭据源。</li><li>停用 API HOME，保留需要的历史数据；移除其独立 API 认证。需要彻底退出 OpenCodex 时，清理其运行状态并卸载包。</li><li>从默认入口重启 App / CLI，运行下面的验收。恢复官方模式时不手工维护一个“官方模型白名单”，让原生运行时按当前账号取得默认列表。</li></ol><p><strong>验收分层</strong>：</p><table tabindex="0"><thead><tr><th>检查</th><th>可接受证据</th></tr></thead><tbody><tr><td>配置</td><td>无第三方 provider、目录和 URL 覆盖；App / CLI 解析到同一 HOME</td></tr><tr><td>认证</td><td>两个运行时的 <code>account/read</code> 都是 <code>chatgpt</code>，需要官方认证；不输出邮箱或 token</td></tr><tr><td>模型</td><td>两个运行时的 <code>model/list</code> 无代理前缀与第三方条目，分页已读完</td></tr><tr><td>后台</td><td>服务、计划任务、托盘、自动启动入口、原监听端口均无残留</td></tr><tr><td>GUI</td><td>重启后的新任务模型菜单与运行时结果一致</td></tr><tr><td>请求</td><td>如果要宣称模型可用，再做一次不含私密材料的最小请求</td></tr></tbody></table><p>App Server 的 <code>initialize → initialized → config/read / account/read / model/list</code> 可以检查原生消费路径；<code>config/read</code> 可能包含敏感设置，应只输出必要字段。[S4]</p><h3 id="常见陷阱与反面证据" tabindex="-1">常见陷阱与反面证据 <a class="header-anchor" href="#常见陷阱与反面证据" aria-label="Permalink to &quot;常见陷阱与反面证据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>解释与处理</th></tr></thead><tbody><tr><td>CLI 可列出模型，App 菜单为空</td><td>已有选择器回归报告；检查内置版本、认证过滤和 GUI，本页不把 CLI 列表当作 GUI 成功。[S10]</td></tr><tr><td>修改目录 JSON 后 App 没变化</td><td>配置参考说明目录在启动时加载；已有 app-server 缓存报告。重启后再核验。[S3][S11]</td></tr><tr><td>某个客户端报 JSON 缺字段</td><td>用匹配运行时的目录结构，两种二进制分别解析。[S5]</td></tr><tr><td>代理停了但 App 仍请求 localhost</td><td>根 URL/profile 还在，或旧进程没有退出；服务停机不等于恢复路由。[E1]</td></tr><tr><td>App 正常，但它启动的 CLI 跑到另一个目录</td><td>检查 <code>shell_environment_policy.set.CODEX_HOME</code> 和终端包装器。[E1]</td></tr><tr><td>旧任务仍显示以前的模型</td><td>新建任务检查默认值；恢复任务可能保留原来的 provider。不要为了整理菜单批量改写会话数据库。</td></tr><tr><td>本地服务检查正常，却不能回答</td><td>服务健康、模型可见、上游认证、Responses 流与工具回合是独立条件。</td></tr></tbody></table><p><strong>证伪结果</strong>：检索发现目录跨版本解析失败、App 选择器过滤、目录缓存三类反例，足以否定“填好 <code>base_url</code> 就全面支持第三方模型”。本教程保留逐入口验收，未验证的 GUI 或上游能力必须继续标为未验证。[S5][S10][S11]</p><p><strong>下一步</strong>：完成一次“选择模型 → 普通文本 → 只读工具调用 → 工具结果继续推理”的闭环，再读 <a href="./integration.html">项目集成</a> 配置 MCP，或回到 <a href="./codex-cli.html">CLI 教程</a> 建立日常操作习惯。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><h3 id="来源与验证范围" tabindex="-1">来源与验证范围 <a class="header-anchor" href="#来源与验证范围" aria-label="Permalink to &quot;来源与验证范围&quot;">​</a></h3><p>以下来源均于 <strong>2026-09-03</strong> 取用。在线文档未标独立发布日期时，以取用日与所列版本为准。</p><table tabindex="0"><thead><tr><th>编号</th><th>来源 / 层级</th><th>用途与范围</th></tr></thead><tbody><tr><td>S1</td><td><a href="https://learn.chatgpt.com/docs/config-file/config-advanced" target="_blank" rel="noreferrer">Advanced Configuration</a>，L0</td><td>HOME、profile 版本迁移、自定义 provider、认证 helper</td></tr><tr><td>S2</td><td><a href="https://learn.chatgpt.com/docs/auth" target="_blank" rel="noreferrer">Authentication</a>，L0</td><td>文件/keyring 认证、第三方 provider 认证选择</td></tr><tr><td>S3</td><td><a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a>，L0</td><td>Responses、模型目录、provider 和认证字段</td></tr><tr><td>S4</td><td><a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a>，L0</td><td>原生配置、账号与模型 RPC；<a href="https://learn.chatgpt.com/docs/reference/settings" target="_blank" rel="noreferrer">App Settings</a> 为配置入口参考</td></tr><tr><td>S5</td><td><a href="https://github.com/openai/codex/issues/38934" target="_blank" rel="noreferrer">Codex #38934</a>，L2 一手复现</td><td>2026-08-17 的 App 内置版本与 <code>main</code> 模型目录不兼容报告；不是官方支持承诺</td></tr><tr><td>S6</td><td><a href="https://opencodex.me/getting-started/installation/" target="_blank" rel="noreferrer">OpenCodex Installation</a>，项目 L0</td><td>HOME 所属、目录注入和 loopback 路由方式</td></tr><tr><td>S7</td><td><a href="https://opencodex.me/guides/providers/" target="_blank" rel="noreferrer">OpenCodex Providers</a>，项目 L0</td><td>上游协议、ChatGPT 与 API key 路由边界</td></tr><tr><td>S8</td><td><a href="https://github.com/openai/codex/blob/rust-v0.153.0/codex-rs/models-manager/src/manager.rs" target="_blank" rel="noreferrer">Codex 0.153.0 models manager</a>，L0 源码</td><td>运行时模型目录、刷新策略和缓存</td></tr><tr><td>S9</td><td><a href="https://opencodex.me/reference/cli/lifecycle/" target="_blank" rel="noreferrer">OpenCodex CLI Lifecycle</a>，项目 L0</td><td>停止、恢复、服务卸载各自职责</td></tr><tr><td>S10</td><td><a href="https://github.com/openai/codex/issues/34487" target="_blank" rel="noreferrer">Codex #34487</a>，L2 一手问题报告</td><td>自定义目录已加载但 GUI 不显示的版本相关反例</td></tr><tr><td>S11</td><td><a href="https://github.com/openai/codex/issues/35129" target="_blank" rel="noreferrer">Codex #35129</a>，L2 一手问题报告</td><td>app-server 静态目录缓存的反例</td></tr><tr><td>E1</td><td>本文 Windows 脱敏实证，E</td><td>两套 HOME 的配置/认证类型、OpenCodex 本机安装与服务、原生运行时检查；原始配置不公开</td></tr><tr><td>E2</td><td>本仓可下载模板的结构检查，E</td><td>两种 Codex 二进制的目录解析、TOML 解析与 PowerShell 语法；不代表真实上游调用或通用 GUI 兼容性</td></tr></tbody></table><h3 id="检索日志" tabindex="-1">检索日志 <a class="header-anchor" href="#检索日志" aria-label="Permalink to &quot;检索日志&quot;">​</a></h3><table tabindex="0"><thead><tr><th>渠道</th><th>原始查询或访问路径</th><th>命中 / 采用</th></tr></thead><tbody><tr><td>官方域搜索</td><td><code>Codex app custom model providers CODEX_HOME configuration</code></td><td>返回结果，改为直接访问配置正文</td></tr><tr><td>官方域搜索</td><td><code>Codex model_catalog_json model providers auth config</code></td><td>返回结果，采用 S1–S3 正文</td></tr><tr><td>官方文档 GET</td><td><code>config-advanced</code>、<code>config-reference</code>、<code>auth</code>、<code>app/settings</code></td><td>4 页成功，旧 URL 重定向至 <code>learn.chatgpt.com</code></td></tr><tr><td>上游 issue 搜索</td><td><code>site:github.com/openai/codex &quot;model_catalog_json&quot; &quot;app&quot;</code></td><td>多条结果，打开并采用 S5、S10、S11</td></tr><tr><td>上游 issue 搜索</td><td><code>site:github.com/openai/codex &quot;CODEX_HOME&quot; &quot;app&quot; &quot;provider&quot;</code></td><td>返回配置相互影响的线索，未作为普遍结论</td></tr><tr><td>OpenCodex GET</td><td><code>getting-started/installation/</code>、<code>guides/providers/</code>、<code>reference/configuration/providers/</code>、<code>reference/cli/lifecycle/</code></td><td>4 页成功，采用安装/provider/生命周期边界</td></tr><tr><td>本机实证</td><td><code>--version</code>、<code>--help</code>、配置键检查、进程/任务/监听检查、App Server RPC</td><td>只保留版本、结构、布尔状态与模型名</td></tr></tbody></table><p><strong>尚未验证</strong>：模板中虚构上游的真实推理与工具回合；所有系统/安装方式下的 GUI 双 HOME 启动；所有第三方模型在当前 App 选择器中的兼容性。配置模板是一套可检查的起点，不能替代这些验收。</p>`,32))])}const v=d(c,[["render",k]]);export{_ as __pageData,v as default};
